      /* ════ 方志/谱牒册页（2026-06-12·替代 codex 版 ppop 样式）════ */
      'body.tm-phase8-formal #ppop.tmf-book{position:fixed;display:none;left:16px;top:62px;bottom:14px;right:auto;z-index:130;width:392px;max-height:none;padding:0;box-sizing:border-box;border:1px solid rgba(96,68,28,.65);border-radius:3px 8px 8px 3px;background:linear-gradient(180deg,var(--ink-50),var(--paper-100) 46%,var(--paper-200));box-shadow:inset 0 0 0 1px rgba(var(--paper-50-rgb),.55),inset 0 0 44px rgba(var(--gold-600-rgb),.16),8px 12px 34px rgba(var(--lacquer-0-rgb),.55);color:var(--paper-ink-900);font-family:"STKaiti","KaiTi","楷体",serif;transition:width .38s cubic-bezier(.6,.05,.25,1);}',
