      'body.tm-phase8-formal #ppop.tmf-book.bk-folded{width:46px;overflow:hidden;}#ppop.tmf-book .bk-inner{position:relative;z-index:3;display:flex;flex-direction:column;height:100%;opacity:1;transition:opacity .18s ease .12s;}#ppop.tmf-book.bk-folded .bk-inner{opacity:0;pointer-events:none;}#ppop.tmf-book.bk-folded .bk-jianqian{opacity:0;pointer-events:none;}#ppop.tmf-book.bk-folded .bk-straddle{opacity:0;}',
      '#ppop.tmf-book .bk-spine{position:absolute;inset:0;z-index:8;display:none;flex-direction:column;align-items:center;cursor:pointer;border-radius:3px 8px 8px 3px;background:linear-gradient(90deg,#7a5a2e,#5d3f20 40%,#4a3118);box-shadow:inset 0 0 0 1px rgba(var(--paper-200-rgb),.14);}#ppop.tmf-book.bk-folded .bk-spine{display:flex;}#ppop.tmf-book .bk-spine .sp-seal{margin:14px 0 10px;width:26px;height:26px;border-radius:50%;border:1.5px solid rgba(var(--vermillion-400-rgb),.9);display:grid;place-items:center;color:#e8b1a8;font-size:calc(11 * var(--tm-px, 1px));background:radial-gradient(circle,rgba(var(--vermillion-450-rgb),.5),rgba(var(--vermillion-600-rgb),.3));}#ppop.tmf-book .bk-spine .sp-label{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;writing-mode:vertical-rl;text-orientation:upright;color:#ecd79b;font-size:calc(14 * var(--tm-px, 1px));letter-spacing:.4em;}#ppop.tmf-book .bk-spine .sp-label small{font-size:calc(10 * var(--tm-px, 1px));color:rgba(var(--gold-100-rgb),.6);letter-spacing:.28em;}',
      '#ppop.tmf-book .bk-straddle{position:absolute;right:-1px;top:46%;width:22px;height:44px;z-index:6;pointer-events:none;opacity:.85;border-radius:22px 0 0 22px;border:2px solid rgba(var(--vermillion-450-rgb),.78);border-right:0;background:radial-gradient(circle at 100% 50%,rgba(var(--vermillion-400-rgb),.30),rgba(var(--vermillion-450-rgb),.16) 60%,transparent);}#ppop.tmf-book .bk-straddle i{position:absolute;left:5px;top:50%;transform:translateY(-50%);font-style:normal;writing-mode:vertical-rl;font-size:calc(9.5 * var(--tm-px, 1px));letter-spacing:2px;color:rgba(var(--vermillion-600-rgb),.85);font-weight:bold;}',
